#include <iostream>
#include <vector>

bool datos_validos(const std::vector<int>& niveles) {
    if (niveles.size() > 8) {
        return false;
    }
    for (int nivel : niveles) {
        if ((nivel < -10) || (nivel > 10)) {
            return false;
        }
    }
    return true;
}

int limitar_nivel(int nivel) {
    if (nivel < 0) {
        return 0;
    }
    if (nivel > 6) {
        return 6;
    }
    return nivel;
}

void normalizar(std::vector<int>& niveles) {
    for (int& nivel : niveles) {
        nivel = limitar_nivel(nivel);
    }
}

int contar_al_limite(const std::vector<int>& niveles) {
    int cuenta = 0;
    for (int nivel : niveles) {
        if (nivel == 6) {
            ++cuenta;
        }
    }
    return cuenta;
}

int main() {
    std::vector<int> niveles = {-5, 4, 10};

    if (!datos_validos(niveles)) {
        std::cout << "Lectures invalides";
    } else {
        normalizar(niveles);
        const int al_limite = contar_al_limite(niveles);
        std::cout << "Niveaux :";
        for (int nivel : niveles) {
            std::cout << " " << nivel;
        }
        std::cout << "\nÀ la limite : " << al_limite;
    }
    return 0;
}

